import{_ as t,o as a,c as d,a3 as s}from"./chunks/framework.BkJHvlZ8.js";const u=JSON.parse('{"title":"平台概览","description":"","frontmatter":{},"headers":[],"relativePath":"guide/overview.md","filePath":"guide/overview.md","lastUpdated":null}'),n={name:"guide/overview.md"};function r(o,e,c,i,l,p){return a(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="平台概览" tabindex="-1">平台概览 <a class="header-anchor" href="#平台概览" aria-label="Permalink to &quot;平台概览&quot;">​</a></h1><p>ApeAdmin 是一个前后端分离的管理底座：后端使用 FastAPI，数据访问使用 SQLAlchemy 2.0 异步会话，前端使用 Vue 3、TypeScript、Vite 和 Element Plus。业务能力通过插件扩展，核心只负责通用的认证、权限、菜单、日志、数据访问和 AI 能力。</p><h2 id="解决什么问题" tabindex="-1">解决什么问题 <a class="header-anchor" href="#解决什么问题" aria-label="Permalink to &quot;解决什么问题&quot;">​</a></h2><ul><li>用统一的用户、角色、菜单和接口权限支撑中后台业务。</li><li>用插件包隔离业务代码，支持运行时启用、停用和资源回收。</li><li>用 MCP 将可授权的管理能力暴露给 AI Agent。</li><li>用统一的异常响应、请求追踪和操作日志降低排查成本。</li></ul><h2 id="运行边界" tabindex="-1">运行边界 <a class="header-anchor" href="#运行边界" aria-label="Permalink to &quot;运行边界&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器</span></span>
<span class="line"><span>  ├─ Vue 管理台（/）</span></span>
<span class="line"><span>  └─ Apehub_web 官网（/apehub-web）</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          └─ FastAPI（/api/v1）</span></span>
<span class="line"><span>               ├─ 核心 API：auth / user / role / menu / dept / plugin</span></span>
<span class="line"><span>               ├─ MCP：tools / resources / prompts / audit-logs</span></span>
<span class="line"><span>               └─ 插件 API：由插件自行挂载</span></span></code></pre></div><p>Apehub_web 是一个普通的 ApeAdmin 插件：它提供官网、插件市场、开发者中心和官网管理 API，但不修改核心路由生成规则。插件启用时挂载 <code>/api/v1/apehub-web</code> 和 <code>/apehub-web</code>；停用时由插件管理器移除其运行时资源并隐藏插件菜单。</p><h2 id="目录速览" tabindex="-1">目录速览 <a class="header-anchor" href="#目录速览" aria-label="Permalink to &quot;目录速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目录</th><th>责任</th></tr></thead><tbody><tr><td><code>backend/src/api</code></td><td>核心 HTTP 路由</td></tr><tr><td><code>backend/src/core</code></td><td>配置、安全、依赖注入、中间件、种子数据</td></tr><tr><td><code>backend/src/db</code></td><td>异步引擎、会话和数据库初始化</td></tr><tr><td><code>backend/src/models</code></td><td>核心 ORM 模型</td></tr><tr><td><code>backend/src/crud</code></td><td>通用 CRUD 与 RBAC 数据操作</td></tr><tr><td><code>backend/src/plugins</code></td><td>插件接口、发现、安装、热启停和资源跟踪</td></tr><tr><td><code>backend/src/mcp</code></td><td>MCP 工具、资源、提示词和审计</td></tr><tr><td><code>backend/src/ai</code></td><td>多模型对话和工具调用循环</td></tr><tr><td><code>frontend/src/router</code></td><td>静态路由、动态菜单路由和权限守卫</td></tr><tr><td><code>frontend/src/views</code></td><td>Vue 页面，路径必须与菜单 component 对应</td></tr></tbody></table><h2 id="关键原则" tabindex="-1">关键原则 <a class="header-anchor" href="#关键原则" aria-label="Permalink to &quot;关键原则&quot;">​</a></h2><ol><li>核心能力放在 <code>backend/src</code>，业务能力放在插件目录。</li><li>插件的菜单、接口、数据表和静态资源必须使用自己的命名空间。</li><li>页面权限只用于前端体验，后端接口必须再次校验权限。</li><li>生产环境使用迁移脚本；<code>init_db()</code> 仅用于开发环境首次启动。</li></ol>`,11)])])}const b=t(n,[["render",r]]);export{u as __pageData,b as default};
